    @Override
    public void setupAnim(TheKing entity, float limbSwing, float limbSwingAmount, float ageInTicks,
                          float netHeadYaw, float headPitch) {
        this.root().getAllParts().forEach(ModelPart::resetPose);
        boolean attack = entity.getAttacking() != 0;
        float speed = attack ? 1.35F : 1.0F;
        // glTF times are in seconds; ageInTicks / 20 = seconds
        float t = (ageInTicks / 20.0F) * speed;
        if (ModelGhidorahAnims.FLY.length > 0) {
            ModelGhidorahAnims.apply(this, ModelGhidorahAnims.FLY, t);
        } else {
            ModelGhidorahAnims.apply(this, ModelGhidorahAnims.IDLE, t);
        }
        // mild attack intensity on torso if present
        if (attack) {
            ModelPart torso = getBone("Torso");
            if (torso != null) {
                torso.xRot += Mth.sin(ageInTicks * 0.4F) * 0.05F;
            }
        }
    }
